import{_ as d,o as e,c as r,al as a}from"./chunks/framework.BawR2jEz.js";const b=JSON.parse('{"title":"Адаптивные изображения","description":"Настройка srcset и sizes у полей с изображениями и замер реальной ширины слота прямо на странице витрины.","frontmatter":{"title":"Адаптивные изображения","description":"Настройка srcset и sizes у полей с изображениями и замер реальной ширины слота прямо на странице витрины."},"headers":[],"relativePath":"responsive-images/index.md","filePath":"responsive-images/index.md"}'),o={name:"responsive-images/index.md"};function s(i,t,n,h,l,p){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="адаптивные-изображения" tabindex="-1">Адаптивные изображения <a class="header-anchor" href="#адаптивные-изображения" aria-label="Permalink to &quot;Адаптивные изображения&quot;">​</a></h1><p>Одно и то же изображение на телефоне и на широком мониторе занимает разное место. Чтобы посетитель не грузил файл на 2000 пикселей ради картинки шириной 250, браузеру дают несколько вариантов файла и подсказку, какой ширины будет место под изображение.</p><p>Этим занимаются две настройки поля:</p><ul><li><strong>srcset</strong> — список готовых файлов: «есть версии на 320, 640, 960 и 1280 пикселей»;</li><li><strong>sizes</strong> — ширина места под изображение: «на десктопе треть экрана, на планшете половина, на телефоне 250 пикселей».</li></ul><p>Браузер берёт <code>sizes</code>, считает нужную ширину с учётом плотности экрана и выбирает подходящий файл из <code>srcset</code>. Плотность он учитывает сам — в настройках её задавать не нужно.</p><h2 id="почему-это-стоит-настроить" tabindex="-1">Почему это стоит настроить <a class="header-anchor" href="#почему-это-стоит-настроить" aria-label="Permalink to &quot;Почему это стоит настроить&quot;">​</a></h2><p>Ошибка в <code>sizes</code> ничем не подсвечивается: страница выглядит рабочей, а результат тихо портится.</p><table tabindex="0"><thead><tr><th>Что не так</th><th>Что видит посетитель</th></tr></thead><tbody><tr><td>Значение занижено</td><td>Браузер берёт файл мельче нужного — изображение мылит</td></tr><tr><td>Значение завышено</td><td>Грузятся лишние сотни килобайт на каждой карточке</td></tr><tr><td>Условия не заданы</td><td>Браузер считает, что изображение во всю ширину экрана, и берёт самый крупный файл</td></tr></tbody></table><p>Последний случай самый частый: расширенный режим включили, список файлов заполнили, а условия — нет.</p><h2 id="где-находится" tabindex="-1">Где находится <a class="header-anchor" href="#где-находится" aria-label="Permalink to &quot;Где находится&quot;">​</a></h2><p>Откройте настройки поля с изображением и включите <strong>Расширенный режим</strong>. Появятся две таблицы — «Атрибут sizes» и «Атрибут srcset» — и кнопка <strong>Замерить на сайте</strong>.</p><p>Настройки доступны у полей: «Изображение», «Список изображений», «Контрольные точки», «YouTube», «Список видео» и «Сетка».</p><h2 id="замер-на-саите" tabindex="-1">Замер на сайте <a class="header-anchor" href="#замер-на-саите" aria-label="Permalink to &quot;Замер на сайте&quot;">​</a></h2><p>Заполнять таблицы вручную не нужно: инструмент откроет страницу вашей витрины, сам прогонит ширину окна от края до края и посчитает значения по фактической вёрстке.</p><h3 id="как-проити-замер" tabindex="-1">Как пройти замер <a class="header-anchor" href="#как-проити-замер" aria-label="Permalink to &quot;Как пройти замер&quot;">​</a></h3><ol><li>Нажмите <strong>Замерить на сайте</strong>. В поле адреса подставлена главная страница витрины — при первом открытии, а дальше та страница, на которой вы закончили в прошлый раз.</li><li>Нажмите <strong>Открыть</strong>. Страница загрузится внутри окна замера.</li><li>Если нужной страницы не видно — просто ходите по сайту прямо в окне: кликайте меню, каталог, карточки. Адрес в поле следует за вами, режим замера при переходах не теряется.</li><li>Нажмите <strong>Выбрать картинку</strong> и кликните по нужному изображению. Под панелью появится его описание.</li><li>При необходимости поправьте диапазон <strong>от</strong> и <strong>до</strong> — по умолчанию 320…1920 пикселей.</li><li>Нажмите <strong>Снять пробы</strong>.</li></ol><p>Инструмент пройдёт диапазон с шагом, замеряя ширину изображения на каждом шаге, а затем уточнит места переломов, чтобы границы совпали с брейкпоинтами вашей вёрстки до пикселя.</p><p>Адрес должен вести на витрину этого же магазина — чужой сайт открыть не получится. Последняя открытая страница запоминается, поэтому в следующий раз окно откроется там же.</p><h3 id="что-показывает-результат" tabindex="-1">Что показывает результат <a class="header-anchor" href="#что-показывает-результат" aria-label="Permalink to &quot;Что показывает результат&quot;">​</a></h3><p><strong>График</strong> — как менялась ширина изображения при изменении ширины окна. По горизонтали ширина окна, по вертикали ширина места под изображение. Наведите курсор — под графиком появится точное значение для этой ширины.</p><p>Ступеньки на графике — это ваши брейкпоинты. Наклонные участки — места, где изображение тянется вместе с окном.</p><p><strong>Таблица участков</strong> — на какие диапазоны разбилась кривая и каким значением описан каждый.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Что означает</th></tr></thead><tbody><tr><td>от / до</td><td>Границы диапазона ширины окна</td></tr><tr><td>слот</td><td>Наибольшая ширина изображения на этом диапазоне</td></tr><tr><td>значение</td><td>То, что попадёт в <code>sizes</code></td></tr><tr><td>слияние с предыдущим</td><td>Насколько вырастет погрешность, если объединить участок с соседним</td></tr></tbody></table><h3 id="подробныи-и-упрощенныи" tabindex="-1">Подробный и упрощённый <a class="header-anchor" href="#подробныи-и-упрощенныи" aria-label="Permalink to &quot;Подробный и упрощённый&quot;">​</a></h3><p>Переключатель над таблицей выбирает, насколько дробным будет результат.</p><p><strong>Подробный</strong> описывает каждую ступеньку вёрстки своим правилом. Точнее всего, но правил получается много, и при правке сетки их придётся перемеривать.</p><p><strong>Упрощённый</strong> объединяет соседние участки с близкими значениями. Правил меньше, поддерживать проще, цена — ширина местами берётся с запасом. Насколько большой запас допустим, задаёт поле <strong>Порог схлопывания</strong>; участки, которые не прошли по порогу, в таблице подписаны — видно, сколько не хватило.</p><p>Запас всегда идёт в безопасную сторону: значение может оказаться крупнее фактического, но никогда не мельче. Файл чуть большего размера лучше, чем мыло.</p><h3 id="плотности-и-шаг-лестницы" tabindex="-1">Плотности и шаг лестницы <a class="header-anchor" href="#плотности-и-шаг-лестницы" aria-label="Permalink to &quot;Плотности и шаг лестницы&quot;">​</a></h3><p>Набор плотностей задаёт, сколько вариантов файла попадёт в <code>srcset</code>.</p><table tabindex="0"><thead><tr><th>Набор</th><th>Когда выбирать</th></tr></thead><tbody><tr><td>только 1×</td><td>Изображение декоративное, чёткость не критична</td></tr><tr><td>1×, 2×</td><td>Обычный выбор: покрывает и обычные экраны, и retina</td></tr><tr><td>1×, 2×, 3×</td><td>Файлы заметно тяжелее, разница на глаз почти не видна</td></tr></tbody></table><p>Каждый участок даёт по варианту на каждую плотность, поэтому их набирается много и часть встаёт вплотную: между файлами на 380 и 400 пикселей браузеру выбирать нечего, а две картинки на диске появятся.</p><p><strong>Шаг лестницы</strong> задаёт, насколько соседние варианты должны отличаться по ширине. По умолчанию 25%: варианты, стоящие ближе, отбрасываются. Уменьшите шаг, если хотите, чтобы браузер подбирал точнее, — файлов станет больше. Самый крупный вариант сохраняется всегда, иначе широким экранам не досталось бы подходящего файла.</p><h3 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to &quot;Применение&quot;">​</a></h3><p>Перед записью показывается сравнение «было / стало» — построчно, с пометками, что добавится, изменится и удалится. Переключателями можно применить только <code>sizes</code>, только <code>srcset</code> или обе таблицы.</p><p>Значения записываются в форму настроек. В базу они попадут после того, как вы сохраните поле обычной кнопкой сохранения.</p><h2 id="перенос-настроек-между-полями" tabindex="-1">Перенос настроек между полями <a class="header-anchor" href="#перенос-настроек-между-полями" aria-label="Permalink to &quot;Перенос настроек между полями&quot;">​</a></h2><p>Замерять одно и то же дважды не нужно: настройки адаптивности переносятся через буфер обмена.</p><table tabindex="0"><thead><tr><th>Кнопка</th><th>Где находится</th><th>Что делает</th></tr></thead><tbody><tr><td>Экспорт</td><td>в окне замера, рядом с «Применить»</td><td>копирует результат замера</td></tr><tr><td>Экспорт</td><td>в настройках поля, рядом с «Замерить на сайте»</td><td>копирует обе таблицы как они сейчас в форме</td></tr><tr><td>Импорт</td><td>там же, в настройках поля</td><td>вставляет скопированное</td></tr></tbody></table><p>Экспорт в окне замера выгружает ровно то, что применилось бы: если переключатель «применить srcset» выключен, в буфер уйдёт только <code>sizes</code>.</p><p>Экспорт из настроек поля берёт таблицы целиком — вместе с хвостом без условия и вручную заданными дескрипторами. Так удобно раздать одну готовую настройку нескольким полям с похожей вёрсткой: карточкам товара, плиткам каталога, миниатюрам блога.</p><p>Импорт открывает окно, куда вставляется скопированный текст. Обе таблицы перезаписываются целиком, но только в форме — не сохранив поле, вы ничего не теряете. Если вставлено что-то другое, окно скажет об этом и останется открытым, чтобы текст можно было поправить.</p><h2 id="что-означают-значения" tabindex="-1">Что означают значения <a class="header-anchor" href="#что-означают-значения" aria-label="Permalink to &quot;Что означают значения&quot;">​</a></h2><p>В колонке «значение» и в готовой строке <code>sizes</code> встречаются три формы записи.</p><table tabindex="0"><thead><tr><th>Форма</th><th>Пример</th><th>Когда появляется</th></tr></thead><tbody><tr><td>Пиксели</td><td><code>403px</code></td><td>Ширина изображения на диапазоне не меняется</td></tr><tr><td>Доля экрана</td><td><code>31.4vw</code></td><td>Изображение тянется вместе с окном</td></tr><tr><td>Вычисление</td><td><code>calc(33.3vw - 23px)</code></td><td>Изображение тянется, но из него вычитаются отступы и промежутки сетки</td></tr></tbody></table><p>Третья форма выглядит непривычно, но именно она описывает сетку с контейнером и отступами точно. Инструмент выбирает её сам, когда простая доля дала бы заметный запас.</p><h2 id="на-что-обратить-внимание" tabindex="-1">На что обратить внимание <a class="header-anchor" href="#на-что-обратить-внимание" aria-label="Permalink to &quot;На что обратить внимание&quot;">​</a></h2><p><strong>Диапазон замера.</strong> Правило самого верхнего участка действует на все ширины выше его границы. Если замерить до 1920, а в вёрстке есть брейкпоинт на 2200, инструмент про него не узнает. Для полноширинных блоков поднимите верхнюю границу.</p><p><strong>Изображение не выводится.</strong> Если на части диапазона изображение скрыто, эти ширины помечаются отдельно и в расчёт не идут — придумывать значение там не из чего.</p><p><strong>Карусели и слайдеры.</strong> Скрипты, которые считают размеры один раз при загрузке страницы, на быструю смену ширины реагируют не всегда. Если числа выглядят странно, нажмите <strong>Перезагрузить</strong> на нужной ширине и повторите замер. Первые замеры на новом макете стоит сверить глазами.</p><p><strong>Если страница не отвечает.</strong> Когда окно замера сообщает, что страница загрузилась, но не отозвалась, оно называет и причину:</p><table tabindex="0"><thead><tr><th>Сообщение</th><th>Что делать</th></tr></thead><tbody><tr><td>Страница ушла на другой домен</td><td>Указать адрес витрины этого магазина</td></tr><tr><td>Открылась без параметра <code>exdoc_preview</code></td><td>Разрешить этот параметр в фильтре запросов или в SEO-модуле — он их часто вырезает</td></tr><tr><td>Скрипт не подключился</td><td>Очистить кэш: страница отдана из него, вместе со старой разметкой</td></tr><tr><td>Скрипт подключён, но молчит</td><td>Посмотреть ошибки в консоли браузера</td></tr></tbody></table><p>Переходы по ссылкам внутри окна замера сохраняют режим. Но если страница открывается из JavaScript или через отправку формы, режим потеряется — тогда вернитесь назад и откройте нужную страницу обычной ссылкой.</p><p><strong>Несколько мест вывода.</strong> Замер описывает то место, по которому вы кликнули. Если поле выводится ещё где-то с другой шириной, значения для того места будут другими.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../fields/image/">Поле «Изображение»</a> — настройки и переменные шаблона</li><li><a href="./../fields/image-list/">Список изображений</a> — галерея с теми же настройками адаптивности</li><li><a href="./../fields/">Поля</a> — все типы полей</li></ul>',56)])])}const g=d(o,[["render",s]]);export{b as __pageData,g as default};
